import csv
import io


_HEADERS = ["sku", "price_cents", "zone", "stock"]


def parse_inventory(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")
    if csv_text == "":
        raise ValueError("incorrect headers")
    if not csv_text.strip():
        return []

    try:
        rows = csv.reader(io.StringIO(csv_text), strict=True)
        header = next(rows)
    except (csv.Error, StopIteration) as exc:
        raise ValueError("invalid CSV") from exc
    if header != _HEADERS:
        raise ValueError("incorrect headers")

    result = []
    try:
        for row in rows:
            if not row or all(not field.strip() for field in row):
                continue
            if len(row) != 4:
                raise ValueError("each row must have four columns")
            sku = row[0].strip()
            zone = row[2].strip()
            if not sku or not zone:
                raise ValueError("sku and zone must be nonempty")
            try:
                price = int(row[1].strip(), 10)
                stock = int(row[3].strip(), 10)
            except ValueError as exc:
                raise ValueError("price and stock must be integers") from exc
            if price < 0 or stock < 0:
                raise ValueError("price and stock must be nonnegative")
            result.append({
                "sku": sku,
                "price_cents": price,
                "zone": zone,
                "stock": stock,
            })
    except csv.Error as exc:
        raise ValueError("invalid CSV") from exc
    return result

